package com.dunerealms.bank;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.sql.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
class BankStoreTest{
 String url;UUID player;BankStore store;AtomicReference<BankStore.Access> access;
 @BeforeEach void setup()throws Exception{url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=5000";player=UUID.fromString("00000000-0000-0000-0009-000000000001");access=new AtomicReference<>(new BankStore.Access(true,true,true));store=new BankStore((c,p)->access.get());try(Connection c=open()){BankStore.initialize(c);BankStore.initialize(c);try(Statement q=c.createStatement()){q.execute("CREATE TABLE dune_economy_balances(uuid VARCHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL)");}try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,250.25)")){q.setString(1,player.toString());q.executeUpdate();}}}
 Connection open()throws Exception{return DriverManager.getConnection(url);}BigDecimal n(String s){return new BigDecimal(s);}
 void amounts(Connection c,boolean staff,String wallet,String bank)throws Exception{assertEquals(0,n(wallet).compareTo(store.wallet(c,player)));assertEquals(0,n(bank).compareTo(store.balance(c,player,staff,false)));}
 @Test void personalTransfersConserveExactCentsAndIsolateIdentities()throws Exception{try(Connection c=open()){c.setAutoCommit(false);store.transfer(c,player,false,false,n("100.10"),UUID.randomUUID());c.commit();amounts(c,false,"150.15","100.10");store.transfer(c,player,false,true,n("20.05"),UUID.randomUUID());c.commit();amounts(c,false,"170.20","80.05");assertEquals(2,store.ledger(c,player,false).size());assertEquals(0,store.balance(c,UUID.randomUUID(),false,false).signum());assertEquals(0,store.balance(c,player,true,false).signum());}}
 @Test void rejectedAmountsOverdraftAndUnknownWalletNeverMintMoney()throws Exception{for(String bad:List.of("0","-1","1.001","1000000.01"))assertThrows(SQLException.class,()->BankStore.amount(n(bad)));try(Connection c=open()){c.setAutoCommit(false);assertThrows(SQLException.class,()->store.transfer(c,player,false,false,n("251"),UUID.randomUUID()));c.rollback();assertThrows(SQLException.class,()->store.transfer(c,player,false,true,n("1"),UUID.randomUUID()));c.rollback();assertThrows(SQLException.class,()->store.transfer(c,UUID.randomUUID(),false,false,n("1"),UUID.randomUUID()));c.rollback();amounts(c,false,"250.25","0");}}
 @Test void ledgerReferenceReplayRejectsBeforeSecondCommittedDebit()throws Exception{UUID id=UUID.randomUUID();try(Connection c=open()){c.setAutoCommit(false);store.transfer(c,player,false,false,n("100"),id);c.commit();assertThrows(SQLException.class,()->store.transfer(c,player,false,false,n("100"),id));c.rollback();amounts(c,false,"150.25","100");assertEquals(1,store.ledger(c,player,false).size());}}
 @Test void rollbackRestoresWalletBankAndReceiptTogether()throws Exception{try(Connection c=open()){c.setAutoCommit(false);store.transfer(c,player,false,false,n("100"),UUID.randomUUID());amounts(c,false,"150.25","100");c.rollback();amounts(c,false,"250.25","0");assertTrue(store.ledger(c,player,false).isEmpty());}}
 @Test void staffPermissionsAreFreshPerMutationAndNoImplicitBypass()throws Exception{try(Connection c=open()){c.setAutoCommit(false);store.transfer(c,player,true,false,n("100"),UUID.randomUUID());c.commit();access.set(new BankStore.Access(true,true,false));assertThrows(SQLException.class,()->store.transfer(c,player,true,true,n("10"),UUID.randomUUID()));c.rollback();access.set(new BankStore.Access(false,true,true));assertThrows(SQLException.class,()->store.transfer(c,player,true,false,n("10"),UUID.randomUUID()));c.rollback();amounts(c,true,"150.25","100");access.set(new BankStore.Access(true,true,true));store.transfer(c,player,true,true,n("20"),UUID.randomUUID());c.commit();amounts(c,true,"170.25","80");}}
 @Test void staffDepositsFromDifferentPlayersShareOneNetworkBalance()throws Exception{UUID other=UUID.randomUUID();try(Connection c=open()){try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_economy_balances VALUES(?,50)")){q.setString(1,other.toString());q.executeUpdate();}c.setAutoCommit(false);store.transfer(c,player,true,false,n("100"),UUID.randomUUID());store.transfer(c,other,true,false,n("30"),UUID.randomUUID());c.commit();assertEquals(0,n("130").compareTo(store.balance(c,other,true,false)));assertEquals(2,store.ledger(c,other,true).size());}}
 @Test void simultaneousWithdrawalsCannotOverdraw()throws Exception{try(Connection c=open()){c.setAutoCommit(false);store.transfer(c,player,false,false,n("100"),UUID.randomUUID());c.commit();}ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);AtomicInteger successes=new AtomicInteger();Callable<Void> action=()->{try(Connection c=open()){c.setAutoCommit(false);start.await();try{store.transfer(c,player,false,true,n("70"),UUID.randomUUID());c.commit();successes.incrementAndGet();}catch(SQLException denied){c.rollback();}}return null;};try{var a=pool.submit(action);var b=pool.submit(action);start.countDown();a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertEquals(1,successes.get());try(Connection c=open()){amounts(c,false,"220.25","30");assertEquals(2,store.ledger(c,player,false).size());}}
 @Test void allWritesRequireFencedTransaction()throws Exception{try(Connection c=open()){assertThrows(SQLException.class,()->store.transfer(c,player,false,false,n("1"),UUID.randomUUID()));assertThrows(SQLException.class,()->store.balance(c,player,false,true));amounts(c,false,"250.25","0");}}
 @Test void sqlPermissionReaderRejectsMismatchedOrAmbiguousIdentity()throws Exception{Connection c=mock(Connection.class);CallableStatement q=mock(CallableStatement.class);ResultSet r=mock(ResultSet.class);when(c.prepareCall(anyString())).thenReturn(q);when(q.execute()).thenReturn(true);when(q.getResultSet()).thenReturn(r);when(r.next()).thenReturn(true,false);when(r.getString("player_uuid")).thenReturn(UUID.randomUUID().toString());assertThrows(SQLException.class,()->BankStore.lockedAccess(c,player));when(r.next()).thenReturn(true,true);when(r.getString("player_uuid")).thenReturn(player.toString());when(r.getInt(anyString())).thenReturn(1);assertThrows(SQLException.class,()->BankStore.lockedAccess(c,player));}
 @Test void displayPresetsArePositiveCappedAndPreserveCents(){assertEquals(Set.of(n("0.25")),DuneBank.amounts(n("0.25")));assertTrue(DuneBank.amounts(n("2000000")).stream().allMatch(v->v.signum()>0&&v.compareTo(n("1000000"))<=0));}
 @Test void debtorWalletCannotDepositAndHasNoPositivePresets()throws Exception{try(Connection c=open()){try(PreparedStatement q=c.prepareStatement("UPDATE dune_economy_balances SET balance=-15.25 WHERE uuid=?")){q.setString(1,player.toString());q.executeUpdate();}assertEquals(0,n("-15.25").compareTo(store.wallet(c,player)));assertTrue(DuneBank.amounts(store.wallet(c,player)).isEmpty());c.setAutoCommit(false);assertThrows(SQLException.class,()->store.transfer(c,player,false,false,n("0.01"),UUID.randomUUID()));c.rollback();amounts(c,false,"-15.25","0");assertTrue(store.ledger(c,player,false).isEmpty());}}
 @Test void factionViewUsesActualPersistedMembershipAndNeverCreatesBalance()throws Exception{try(Connection c=open()){try(Statement q=c.createStatement()){q.execute("CREATE TABLE dune_players(uuid VARCHAR(36) PRIMARY KEY,faction VARCHAR(64))");q.execute("CREATE TABLE dune_faction_bank_wallet(faction_id VARCHAR(32) PRIMARY KEY,balance DECIMAL(20,2))");q.execute("CREATE TABLE dune_faction_bank_ledger(id VARCHAR(36),faction_id VARCHAR(32),action VARCHAR(32),delta DECIMAL(20,2),balance_after DECIMAL(20,2),created_at BIGINT)");q.execute("INSERT INTO dune_faction_bank_wallet VALUES('atreides',15.25)");}try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_players VALUES(?,'Atreides')")){q.setString(1,player.toString());q.executeUpdate();}var v=store.faction(c,player);assertEquals("atreides",v.faction());assertEquals(0,n("15.25").compareTo(v.balance()));assertTrue(v.ledger().isEmpty());try(PreparedStatement q=c.prepareStatement("UPDATE dune_players SET faction='Harkonnen' WHERE uuid=?")){q.setString(1,player.toString());q.executeUpdate();}v=store.faction(c,player);assertEquals("harkonnen",v.faction());assertEquals(0,v.balance().signum());try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT COUNT(*) FROM dune_faction_bank_wallet")){r.next();assertEquals(1,r.getInt(1));}assertThrows(SQLException.class,()->store.faction(c,UUID.randomUUID()));}}
}
